// Generated by bundle-improver.mjs.
export const AUTHORED_IMPROVER = {
  "componentSearchStep/chooseComponents.nl": "---\nargs:\n  facts: ComponentFacts\nreturns: string[]\n---\nChoose the component keys the next edit rewrites. facts.eligible lists the keys that training cases cover, each with coveredCases (cases that exercise it), failingCases (covered cases that scored below 1), proposals (edits already tried) and accepts (edits accepted).\n\n1. Choose the key with the highest failingCases.\n2. When several keys tie, choose the one with the smallest proposals, then the smallest key.\n3. Return a list holding that key. The host adds the keys it depends on.\n",
  "componentSearchStep/chooseMove.nl": "---\nargs:\n  facts: MoveFacts\nreturns: string\n---\nChoose the kind of the next experiment: `edit` rewrites the selected components of one parent, `compose` merges two population members. facts.members lists the population with changedKeys, the component keys each member changed relative to the baseline; facts.iteration is the experiment number.\n\n1. When facts.members has fewer than two members, return `edit`.\n2. When two members have changedKeys lists that share no key, return `compose`: their changes can be merged without conflict.\n3. Otherwise return `edit`.\n",
  "componentSearchStep/rewriteComponents.nl": "---\nkind: directory-reducer\nargs:\n  request: ComponentRewriteRequest\nreturns: Candidate\n---\nImprove the selected instruction components using the supplied training feedback. This is a typed edit of the component source folder.\n\nRead components.json. Each value is either {kind:'program.guidance',text:string} or {kind:'lambda.instructions',template:{segments:string[],slotIds:string[]}}. Edit only request.keys. Keep every kind, slotIds, unselected component, and the number of segments unchanged. Static segments are ordinary string arrays: do not encode an array as a string. Preserve the behavior expected by the examples and immutable component contracts. request.feedback is a pageable read-only view: inspect request.feedback.length and request.feedback.page(start, limit) (at most 200 records per page). Select useful evidence without discarding the rest. Use it to identify a specific failure and repair its instructions concisely.\n\nWrite the complete revised candidate to components.json, then return that exact object with `return candidate;` in an eval. Do not merely inspect it. The returned value and edited file must agree.\n",
  "componentSearchStep.nl": "---\nkind: directory-reducer\nargs:\n  state: ComponentLoopState\nreturns: ComponentLoopState\n---\nPerform one component-search experiment and return the next joint source/state checkpoint. You own experiment sequencing. The search service supplies exact GEPA selection math, declared dependencies, independent evaluation and checked state assembly; it never runs a search loop.\n\nCall search.plan(state.iteration). This draws the seeded per-case frontier parent and dependency update group, charges one experiment, and supplies the parent's typed component values plus complete training feedback. If stopReason is coverage-gap, finish with that stop reason and no acceptance. Otherwise install plan.parent in folder's components.json before proposing edits.\n\nWhen plan.compose is true, call search.merge() for conservative three-way composition. A conflict gives null; then use a normal proposal. For a normal proposal, call folder.propose(rewriteComponents, {keys:plan.keys,components:plan.components,feedback:plan.feedback}). The returned value must equal the edited components.json. The rewrite child can page feedback rather than receiving a truncated first dozen examples.\n\nCall search.check(candidate). A rejected check finishes this experiment with accepted:false and concrete diagnostics. Duplicates in plan.duplicateIds finish without evaluation or acceptance. For a new valid candidate, evaluate both parent and candidate on the same minibatch using search.evaluate(id,'mini',true) and search.evaluate(id,'mini'). Accept only when candidate gates pass and its quality strictly exceeds the parent's. A rejection still records a completed experiment. For an accepted candidate, explicitly evaluate full training and validation using search.evaluate(id,'train') and search.evaluate(id,'validation'); pass their evidence references to search.finish.\n\nsearch.finish({candidate:id,accepted,train:training.evidence,validation:validated.evidence}) verifies exact acceptance, applies validation constraints and guidance coverage, protects the baseline/incumbent while pruning the per-case frontier, and returns {state,candidate}. It does not choose semantic edits. For an invalid proposal use {accepted:false,error:reason}. Never catch exhaustion or cancellation to create more capacity. The state iteration advances exactly once for each charged experiment.\n\nFinally write returned candidate to folder.file('components.json') and explicitly `return finished.state;` from eval. The selected source can differ from the proposed child: preserve that distinction. Test evidence is absent and cannot drive this experiment. Do not fabricate metrics or ask for a host optimizer endpoint. Reply done after returning the completed typed state.\n",
  "counterexampleStep/suggestCounterexamples.nl": "---\nargs:\n  goal: string\n  evidence: unknown[]\n  maxSuggestions?: number\nreturns: CounterexampleSuggestions\n---\nSuggest concrete deployment inputs that distinguish a plausible faulty implementation from the requested behavior.\n\n1. Read goal and the training failures in evidence.\n2. Name the boundary or interaction that the failures suggest is untested.\n3. Write at most maxSuggestions argument lists (four when it is absent) that exercise it, in inputs.\n4. Write reason: one sentence on what the inputs probe.\n\nExpected outcomes belong to the independent oracle, which checks the inputs; return the inputs alone.\n",
  "counterexampleStep.nl": "---\nkind: directory-reducer\nargs:\n  state: CounterexampleState\n  goal: string\nreturns: CounterexampleState\n---\nPerform one counterexample-guided repair experiment. The suite's expected outcomes belong to an independent author-provided oracle. Never supply or alter gold yourself.\n\nRead folder.snapshot() and ask counterexamples.evidence for its training failures. Call suggestCounterexamples with goal and that evidence; it returns {inputs, reason}, inputs exposing a missing behavior. Ask counterexamples.admit to check suggestion.inputs against the independent oracle. It returns the new suite identity, admitted count and remaining check allowance; validation and test cases remain pinned. If none were admitted, retain source and stop with an honest reason.\n\nIf examples were admitted, call counterexamples.repair(folder.snapshot()) to run the ordinary authored improvement program on the new suite. Install its actual returned source with await folder.select(result.folder), and record its disposition and measured quality. Stop when the repaired training suite passes, checks are exhausted, or this experiment failed to produce a completed eligible repair. Increment state.round exactly once. Return the typed next state with the actual suite identity, remaining checks, quality, done and reason. Never invent additional capacity or evaluate a target yourself.\n",
  "improveStep/baseline.ts": "import type {SearchState} from '../types';\ntype MeasuredSource = {source:string;quality:number;sourceBytes?:number;modelCalls?:number;scores?:{caseId:string;quality:number}[]};\n/** Assemble baseline state without asking the model to reproduce its schema. */\nexport function start(state:SearchState,baseline:MeasuredSource):SearchState {\n  return {...state,incumbent:baseline.source,quality:baseline.quality,population:[{source:baseline.source,quality:baseline.quality,parent:'',...(baseline.sourceBytes!==undefined?{cost:baseline.sourceBytes}:{}),...(baseline.modelCalls!==undefined?{modelCalls:baseline.modelCalls}:{}),...(baseline.scores?{scores:baseline.scores}:{})}]};\n}\n",
  "improveStep/capabilities.ts": "import type {Diagnosis,DiagnoseRequest,EditRequest,EditResult,ExperimentOutcome,Hypothesis,HypothesizeRequest,ImprovementPolicy,Opportunity,OpportunityFacts,PopulationMember,StopDecision,StopFacts,TrainingEvidence} from '../types';\n\ntype Measurement={source:string;quality:number;sourceBytes:number;modelCalls?:number;gatesPassed:boolean;evidence:string;scores?:{caseId:string;quality:number}[]};\ntype Proposal={folder:Snapshot;value:EditResult;diff:{changes:{path:string}[]}};\nexport type Snapshot={digest:string;filePaths():string[];readText(path:string):Promise<string>;branch():Draft};\ntype Draft={filePaths():string[];readText(path:string):Promise<string>;propose(reducer:unknown,request:EditRequest):Promise<Proposal>;accept(proposal:Proposal):Promise<Snapshot>};\nexport type ExperimentFolder={at(source:string):Snapshot};\nexport type ExperimentEvaluator={evaluate(source:Snapshot,request:{split:'train'|'validation';seed:number}):Promise<Measurement>;page(reference:string):TrainingEvidence[];check(source:Snapshot):Promise<{valid:boolean;diagnostics:string[]}>};\n/** What an experiment decides with: the pluggable search policies and the semantic stages (policies.ts supplies them). */\nexport type Decisions={\n  findOpportunity(policy:ImprovementPolicy,facts:OpportunityFacts):Promise<Opportunity>;\n  chooseParent(policy:ImprovementPolicy,population:PopulationMember[],history:ExperimentOutcome[],seed:number):Promise<string>;\n  selectIncumbent(policy:ImprovementPolicy,population:PopulationMember[],incumbent:string):Promise<string>;\n  shouldStop(policy:ImprovementPolicy,facts:StopFacts):Promise<StopDecision>;\n  diagnose(request:DiagnoseRequest):Promise<Diagnosis>;\n  hypothesize(request:HypothesizeRequest):Promise<Hypothesis>;\n  editor(mode:'instruction'|'structural'):unknown;\n};\n/** The journal of experiment plans (the `plans` service): a resumed run recalls the plan recorded before the edit. */\nexport type PlanJournal={recall(iteration:number):Promise<unknown>;record(iteration:number,plan:unknown):Promise<void>};\n",
  "improveStep/chooseParent.nl": "---\nargs:\n  members: ParentChoice[]\nreturns: string\n---\nChoose which population member the next experiment starts from. Each member has an id, its validation quality, wonCases (the cases where it has the highest score in the population) and timesParent (how often it has been a parent).\n\n1. Keep the members whose wonCases list is not empty. When none remains, keep all members.\n2. Among those, prefer the member with the smallest timesParent.\n3. When several members tie, prefer the one with the higher quality, then the smaller id.\n4. Return the id of that member.\n",
  "improveStep/context.ts": "import {transformationText} from './transformations';\nimport type {ImprovementPolicy,EditRequest,Diagnosis,Hypothesis,TrainingEvidence,SourceFile,ExperimentFeedback} from '../types';\n\n/** How much of each part the compact card shows; the complete text stays in the typed arguments. */\nexport const CLIPS={diagnostic:700,candidate:900,source:1200,error:400,observed:700,effects:1000,action:220,observation:400,card:6000};\n\n/** What the edit stage reads: the hypothesis, its diagnosis and the source, with the compact card for orientation. */\nexport function request(policy:ImprovementPolicy,hypothesis:Hypothesis,diagnosis:Diagnosis,evidence:TrainingEvidence[],sourceFiles:SourceFile[],lastExperiment?:ExperimentFeedback):EditRequest {\n  const serviceDeclarations=evidence.find(row=>row.serviceDeclarations)?.serviceDeclarations;\n  return {brief:brief(policy,evidence,sourceFiles,lastExperiment),goal:policy.goal,mode:policy.mode,objective:policy.objective??'quality',hypothesis,diagnosis,sourceFiles,allowedFiles:policy.allowedFiles,\n    ...(serviceDeclarations?{serviceDeclarations}:{}),...(policy.transformation?{transformation:transformationText(policy.transformation)}:{})};\n}\n\n/** A small first read; complete source and observations remain available in the typed context. */\nexport function brief(policy:ImprovementPolicy,evidence:TrainingEvidence[],sourceFiles:SourceFile[],lastExperiment?:ExperimentFeedback):string {\n  const lines=['Goal: '+policy.goal,'Mode: '+policy.mode+'; objective: '+(policy.objective??'quality'),'Allowed source edits: '+policy.allowedFiles.join(', ')];\n  if(lastExperiment){\n    lines.push('Previous experiment: '+lastExperiment.reason);\n    for(const diagnostic of lastExperiment.diagnostics??[])lines.push('Previous diagnostic: '+diagnostic.slice(0,CLIPS.diagnostic));\n    for(const file of lastExperiment.sourceFiles.filter(file=>!sourceFiles.some(current=>current.path===file.path&&current.text===file.text)))lines.push('Previous candidate '+file.path+':\\n'+file.text.slice(0,CLIPS.candidate));\n  }\n  for(const file of sourceFiles)lines.push('Source '+file.path+':\\n'+file.text.slice(0,CLIPS.source)+(file.text.length>CLIPS.source?'\\n[clipped; full text in sourceFiles]':''));\n  for(const row of evidence){\n    lines.push('Training '+(row.caseId??'case')+': '+(row.passed?'passed':'failed')+'; model requests '+(row.modelCalls??'unknown')+(row.failureKind?'; '+row.failureKind:'')+(row.error?'; '+row.error.slice(0,CLIPS.error):''));\n    if(!row.passed)lines.push('Observed: '+JSON.stringify({args:row.args,value:row.value,expected:row.expected}).slice(0,CLIPS.observed));\n    if(!row.passed&&row.expectedFiles){\n      const paths=[...new Set([...Object.keys(row.expectedFiles),...Object.keys(row.files??{})])].sort();\n      const differences=paths.filter(path=>row.files?.[path]!==row.expectedFiles?.[path]).map(path=>({path,actual:row.files?.[path]??'<missing>',expected:row.expectedFiles?.[path]??'<absent>'}));\n      lines.push('File effects: '+(row.files?JSON.stringify(differences).slice(0,CLIPS.effects):'result unavailable; expected '+JSON.stringify(row.expectedFiles).slice(0,CLIPS.observed)));\n    }\n    for(const step of row.modelTrace??[]){\n      const calls=step.calls as {name:string;arguments?:Record<string,unknown>}[];\n      lines.push('Action: '+calls.map(call=>call.name+' '+JSON.stringify(call.arguments??{}).slice(0,CLIPS.action)).join('; '));\n      if(/error|rejected|failed/i.test(step.observation))lines.push('Tool observation: '+step.observation.slice(0,CLIPS.observation));\n    }\n  }\n  const result=lines.join('\\n');\n  return result.slice(0,CLIPS.card)+(result.length>CLIPS.card?'\\n[card clipped; inspect the implicated sourceFiles or evidence field]':'');\n}\n",
  "improveStep/crisp.ts": "import {chooseIncumbent,drawParent,leaders,wonCases,type Member} from 'natlang:gepa';\nimport type {ExperimentOutcome,ImprovementPolicy,IncumbentChoice,Objective,Opportunity,OpportunityFacts,ParentChoice,PopulationMember,StopDecision,StopFacts,TrainingEvidence} from '../types';\n\n/**\n * The crisp side of the search policies: the defaults, which equal the program's behavior before the policies were\n * pluggable, and the verifiers that bound a natural-language choice. Pure functions; no model is called here.\n * policies.ts wires each default and its natural-language function into one pluggable policy.\n */\nconst must=(ok:boolean,message:string):void=>{if(!ok)throw Error(message);};\n\n/** The selection math reads members by id; a population member is identified by its source digest. */\nexport function members(population:PopulationMember[]):Member[] {\n  return population.map(member=>({id:member.source,quality:member.quality,scores:member.scores??[],...(member.cost!==undefined?{cost:member.cost}:{}),...(member.modelCalls!==undefined?{modelCalls:member.modelCalls}:{})}));\n}\n\n/** The rows an opportunity is judged from. */\nexport function opportunityFacts(policy:ImprovementPolicy,evidence:TrainingEvidence[]):OpportunityFacts {\n  return {objective:policy.objective??'quality',rows:evidence.map(row=>({caseId:row.caseId??'case',passed:row.passed,...(row.modelCalls!==undefined?{modelCalls:row.modelCalls}:{}),...(row.failureKind?{failureKind:row.failureKind}:{})}))};\n}\n/** Identify an evidenced objective; the model still decides which change can help. */\nexport function crispOpportunity(facts:OpportunityFacts):Opportunity {\n  const failed=facts.rows.filter(row=>!row.passed).map(row=>row.caseId);\n  if(facts.rows.some(row=>row.failureKind==='fixture'))return {kind:'fixture',reason:'Independent fixture failed before target execution.'};\n  if(failed.length)return {kind:'quality',reason:'A current target execution failed; diagnose its actual outcome and trace.'};\n  if(facts.objective==='model-calls'&&facts.rows.some(row=>row.modelCalls!==undefined&&row.modelCalls>1))return {kind:'efficiency',reason:'Correct answers still took multiple model requests. Inspect the trace for avoidable inspection, repair, delegation or a separate completion request. Passing quality does not complete the cost objective.'};\n  if(facts.objective==='source-size')return {kind:'source-size',reason:'Correct answers permit a behavior-preserving source simplification; test a real size reduction.'};\n  return {kind:'none',reason:'No observed failure or cost opportunity supports this objective.'};\n}\n/** An opportunity must be supported by the rows: `fixture` and `quality` need such a row, `efficiency` a passing one. */\nexport function verifyOpportunity(found:Opportunity,facts:OpportunityFacts):Opportunity {\n  const kinds=['fixture','quality','efficiency','source-size','none'];\n  must(kinds.includes(found.kind),'An opportunity kind is one of '+kinds.join(', ')+'.');\n  must((found.kind==='fixture')===facts.rows.some(row=>row.failureKind==='fixture'),'The kind is `fixture` exactly when a training row has failureKind `fixture`.');\n  must(found.kind!=='quality'||facts.rows.some(row=>!row.passed),'The kind `quality` needs a failed training row.');\n  must(found.kind!=='efficiency'||facts.rows.some(row=>row.passed),'The kind `efficiency` needs a passing training row.');\n  return found;\n}\n\n/** The population as parent candidates: the cases each wins and how often it has been a parent. */\nexport function parentChoices(population:PopulationMember[],history:ExperimentOutcome[]):ParentChoice[] {\n  const won=wonCases(members(population));\n  return population.map(member=>({id:member.source,quality:member.quality,wonCases:won[member.source]??[],timesParent:history.filter(outcome=>outcome.parent===member.source).length}));\n}\n/** The crisp parent: a seeded draw over the per-case frontier. */\nexport function crispParent(population:PopulationMember[],seed:number):string {\n  return drawParent(members(population),seed).id;\n}\n/** A parent is a population member. */\nexport function verifyParent(id:string,population:PopulationMember[]):string {\n  must(population.some(member=>member.source===id),'A parent is the id of a population member; choose one of: '+population.map(member=>member.source).join(', ')+'.');\n  return id;\n}\n\n/** The members an incumbent may be: the highest quality, narrowed by the objective's measure. */\nexport function incumbentChoices(population:PopulationMember[],objective:Objective):IncumbentChoice[] {\n  const allowed=leaders(members(population),objective);\n  return population.filter(member=>allowed.includes(member.source)).map(member=>({id:member.source,quality:member.quality,...(member.cost!==undefined?{sourceBytes:member.cost}:{}),...(member.modelCalls!==undefined?{modelCalls:member.modelCalls}:{})}));\n}\n/** The crisp incumbent: the current one while it remains a leader, otherwise the leader with the smallest id. */\nexport function crispIncumbent(population:PopulationMember[],incumbent:string,objective:Objective):string {\n  return chooseIncumbent(members(population),incumbent,objective);\n}\n/** The incumbent is among the best-quality members. */\nexport function verifyIncumbent(id:string,population:PopulationMember[],objective:Objective):string {\n  const allowed=leaders(members(population),objective);\n  must(allowed.includes(id),'The incumbent is one of the best-quality members: '+allowed.join(', ')+'.');\n  return id;\n}\n\n/** The stop decision of the declared defaults. */\nexport function crispStop(facts:StopFacts):StopDecision {\n  if(facts.disposition==='fixture-error')return {stop:true,reason:facts.reason};\n  if(facts.selectedQuality===1&&facts.objective==='quality')return {stop:true,reason:'Declared objective satisfied.'};\n  if(facts.disposition==='no-hypothesis'||facts.disposition==='no-opportunity')return {stop:true,reason:'No further evidenced change.'};\n  if(facts.iteration+1>=facts.maxExperiments)return {stop:true,reason:'Declared experiments completed.'};\n  return {stop:false,reason:'Continue with a distinct hypothesis.'};\n}\n/** A stop below `maxExperiments` is allowed; a continue at it is not. */\nexport function verifyStop(decision:StopDecision,facts:StopFacts):StopDecision {\n  must(typeof decision.stop==='boolean','A stop decision has a boolean `stop`.');\n  must(decision.stop||facts.iteration+1<facts.maxExperiments,'The search stops when iteration + 1 reaches maxExperiments ('+facts.maxExperiments+').');\n  return decision;\n}\n",
  "improveStep/diagnose.nl": "---\nargs:\n  request: DiagnoseRequest\nreturns: Diagnosis\n---\nSay what the training evidence shows about the program, relative to request.goal. The result is a diagnosis: observations and the pattern they share.\n\n1. Read request.opportunity.kind and request.opportunity.reason. They name which rows of request.evidence to read: the failed rows for `quality`; the passing rows that used more than one model request for `efficiency`; the passing rows for `source-size`.\n2. For each such row write one observation with these fields. caseId is the row's caseId. whatHappened states what the program did: its result, the files it wrote and the actions in its trace. expected states what the goal asks for on that row. category is `wrong-result` when the result differs from the expected one, `execution-method` when the trace calls something that is unavailable or uses a file method that does not exist, `wasted-action` when a model request or tool call did not change the result, and `fixture` when the row failed before the program ran.\n3. When request.lastExperiment is present, add one observation per training row that still fails, naming what that experiment changed and what its measurements show. Read request.history for the outcomes of earlier experiments.\n4. Write pattern: one sentence on what several observations have in common. When the observations share nothing, write the most frequent category and the case ids it covers.\n\nrequest.brief is a compact card of the same evidence; read it first and open a row of request.evidence when a detail is needed.\n",
  "improveStep/editSource.nl": "---\nkind: directory-reducer\nargs:\n  request: EditRequest\nreturns: EditResult\n---\nMake the edit that request.hypothesis describes in the program source held in folder, and report it. The goal describes what the edited program must do when it runs.\n\n1. Read request.sourceFiles; they hold the current text of every existing source path. Read request.hypothesis for the kind of edit, the files to change and the expected effect, and request.diagnosis for the cases behind it.\n2. Edit the paths in request.hypothesis.files, which are among request.allowedFiles. Create a path that does not exist yet by writing it. The files the program writes when it runs (such as report.json) belong to its runtime folder; express how the program produces them in its source.\n3. Change prose only: rewrite the instructions in the natural-language text, and keep TypeScript, callable contracts and interpolation bindings as they are. State each rule once, in its narrowest scope; merge instructions that repeat each other and resolve instructions that contradict each other.\n4. Write each judgment as an instruction that reads the input's meaning. Take service field names and enum meanings from request.serviceDeclarations. Describe paths and counts as runtime data, so the program holds across the training folders.\n5. When request.transformation is present, it names the kind of change this run performs; keep the edit within that kind and keep every behavior listed in request.preserves.\n6. Return summary, one sentence naming the observed failure or wasted action the edit addresses, and preserves, the external behaviors the edit keeps.\n",
  "improveStep/editSourceStructural.nl": "---\nkind: directory-reducer\nargs:\n  request: EditRequest\nreturns: EditResult\n---\nMake the edit that request.hypothesis describes in the program source held in folder, and report it. The goal describes what the edited program must do when it runs.\n\n1. Read request.sourceFiles; they hold the current text of every existing source path. Read request.hypothesis for the kind of edit, the files to change and the expected effect, and request.diagnosis for the cases behind it.\n2. Edit the paths in request.hypothesis.files, which are among request.allowedFiles. Create a path that does not exist yet by writing it. The files the program writes when it runs (such as report.json) belong to its runtime folder; express how the program produces them in its source.\n3. Reorganize the execution structure as the hypothesis requires. The .nl interpreter judges visible inputs directly, so a root reducer can read a small batch, judge its meaning and do the exact bookkeeping in one final eval. Keep exact code for counting, parsing and arithmetic. Hand a semantic batch to a separate function when that subproblem stands on its own. When the hypothesis names a helper, read the helper and change or replace it.\n4. Write each judgment as an instruction that reads the input's meaning. Take service field names and enum meanings from request.serviceDeclarations. Describe paths and counts as runtime data, so the program holds across the training folders.\n5. When request.transformation is present, it names the kind of change this run performs; keep the edit within that kind and keep every behavior listed in request.preserves.\n6. Return summary, one sentence naming the observed failure or wasted action the edit addresses, and preserves, the external behaviors the edit keeps.\n",
  "improveStep/experiment.ts": "import {better,objectiveMeasure} from 'natlang:gepa';\nimport type {Disposition,ExperimentResult,ExperimentFeedback,Hypothesis,ImprovementPolicy,SearchState} from '../types';\nimport type {ExperimentFolder,ExperimentEvaluator,Decisions} from './capabilities';\nimport {brief,request} from './context';\nimport {inspect} from './feedback';\nimport {transformationText} from './transformations';\n\n/** A hypothesis names files among the allowed ones, and a statement unless it proposes no edit. */\nexport function hypothesisProblem(hypothesis:Hypothesis,policy:ImprovementPolicy):string {\n  const outside=hypothesis.files.filter(path=>!policy.allowedFiles.includes(path));\n  if(outside.length)return 'A hypothesis names files among the allowed ones ('+policy.allowedFiles.join(', ')+'); these are not: '+outside.join(', ')+'.';\n  if(!hypothesis.statement.trim())return 'A hypothesis has a statement naming the observed failure or wasted action it addresses.';\n  if(hypothesis.kind==='structure'&&policy.mode!=='structural')return 'The kind `structure` belongs to structural mode; this run is in '+policy.mode+' mode.';\n  return '';\n}\n\n/** One finite experiment. Diagnosis, hypothesis and the source edit are semantic decisions; everything else is exact. */\nexport async function test(folder:ExperimentFolder,evaluator:ExperimentEvaluator,parentId:string,policy:ImprovementPolicy,state:SearchState,decide:Decisions):Promise<ExperimentResult> {\n  const seed=policy.seed??0;\n  const parent=folder.at(parentId).branch();\n  const measured=await evaluator.evaluate(folder.at(parentId),{split:'validation',seed});\n  const feedback=await inspect(folder,evaluator,parentId,policy,decide);\n  const ended=(disposition:Disposition,reason:string,candidate?:string,failing?:ExperimentResult['failing'],detail?:ExperimentFeedback):ExperimentResult=>({source:parentId,parent:parentId,accepted:false,disposition,reason,quality:measured.quality,sourceBytes:measured.sourceBytes,...(measured.modelCalls!==undefined?{modelCalls:measured.modelCalls}:{}),scores:measured.scores??[],...(candidate?{candidate}:{}),...(failing?{failing}:{}),...(detail?{feedback:detail}:{})});\n  if(feedback.opportunity.kind==='fixture')return ended('fixture-error',feedback.evidence.filter(row=>row.failureKind==='fixture').map(row=>row.error??'Independent fixture failed.').join('\\n'));\n  if(feedback.opportunity.kind==='none')return ended('no-opportunity',feedback.opportunity.reason);\n  const paths=parent.filePaths();\n  const sourceFiles=await Promise.all(paths.map(async path=>({path,text:await parent.readText(path)})));\n  const history=state.history;\n  const card=brief(policy,feedback.evidence,sourceFiles,state.lastExperiment);\n  const diagnosis=await decide.diagnose({evidence:feedback.evidence,brief:card,goal:policy.goal,objective:policy.objective??'quality',opportunity:feedback.opportunity,history,...(state.lastExperiment?{lastExperiment:state.lastExperiment}:{})});\n  const transformation=policy.transformation?transformationText(policy.transformation):undefined;\n  const hypothesis=await decide.hypothesize({diagnosis,sourceFiles,mode:policy.mode,allowedFiles:policy.allowedFiles,history,...(transformation?{transformation}:{})});\n  if(hypothesis.kind==='none')return ended('no-hypothesis','No supported hypothesis: '+hypothesis.statement);\n  const problem=hypothesisProblem(hypothesis,policy);\n  if(problem)return ended('invalid-candidate',problem);\n  const proposal=await parent.propose(decide.editor(policy.mode),request(policy,hypothesis,diagnosis,feedback.evidence,sourceFiles,state.lastExperiment));\n  if(!proposal.diff.changes.length)return ended('no-hypothesis','The edit left the source unchanged.');\n  const candidateId=proposal.folder.digest;\n  if(candidateId===parentId||state.population.some(member=>member.source===candidateId)||history.some(outcome=>outcome.candidate===candidateId))return ended('duplicate','This candidate repeats an earlier one; choose an edit that differs from every earlier outcome.',candidateId);\n  const candidatePaths=proposal.folder.filePaths();\n  const candidateFiles=await Promise.all(candidatePaths.map(async path=>({path,text:await proposal.folder.readText(path)})));\n  const checked=await evaluator.check(proposal.folder);\n  if(!checked.valid){const reason='Compilation rejected: '+checked.diagnostics.join('\\n');return ended('invalid-candidate',reason,candidateId,undefined,{sourceFiles:candidateFiles,training:[],reason});}\n  const training=await evaluator.evaluate(proposal.folder,{split:'train',seed});\n  const candidate=await evaluator.evaluate(proposal.folder,{split:'validation',seed});\n  const objective=policy.objective??'quality';\n  const improvement=better({quality:candidate.quality,cost:candidate.sourceBytes,modelCalls:candidate.modelCalls},{quality:measured.quality,cost:measured.sourceBytes,modelCalls:measured.modelCalls},{measure:objectiveMeasure(objective)});\n  const reason='Measured candidate: train quality '+training.quality+', validation quality '+candidate.quality+' vs '+measured.quality+', validation calls '+candidate.modelCalls+' vs '+measured.modelCalls+', bytes '+candidate.sourceBytes+' vs '+measured.sourceBytes+'.';\n  const trainingRows=evaluator.page(training.evidence);\n  const diagnostics=trainingRows.map(row=>'Train '+(row.caseId??'case')+': '+(row.passed?'passed':'failed; actual '+JSON.stringify(row.value)+', expected '+JSON.stringify(row.expected))+'; requests '+(row.modelCalls??'unknown')+(row.error?'; '+row.error:'')).map(text=>text.slice(0,700));\n  const candidateFeedback:ExperimentFeedback={diagnostics,sourceFiles:candidateFiles,training:trainingRows,validation:{quality:candidate.quality,...(candidate.modelCalls!==undefined?{modelCalls:candidate.modelCalls}:{})},reason};\n  const failing=trainingRows.filter(row=>!row.passed).map(row=>row.caseId??'case');\n  if(!training.gatesPassed||!candidate.gatesPassed||!improvement)return ended('rejected',reason,candidateId,failing,candidateFeedback);\n  const installed=await parent.accept(proposal);\n  return {source:installed.digest,parent:parentId,accepted:true,disposition:'accepted',reason:proposal.value.summary,candidate:candidateId,failing,quality:candidate.quality,sourceBytes:candidate.sourceBytes,...(candidate.modelCalls!==undefined?{modelCalls:candidate.modelCalls}:{}),scores:candidate.scores??[],feedback:candidateFeedback};\n}\n",
  "improveStep/feedback.ts": "import type {ImprovementPolicy,Opportunity,TrainingEvidence} from '../types';\nimport type {ExperimentFolder,ExperimentEvaluator,Decisions} from './capabilities';\nimport {opportunityFacts} from './crisp';\n/** Read measured training feedback, never validation answers. */\nexport async function inspect(folder:ExperimentFolder,evaluator:ExperimentEvaluator,parentId:string,policy:ImprovementPolicy,decide:Pick<Decisions,'findOpportunity'>):Promise<{evidence:TrainingEvidence[];opportunity:Opportunity}> {\n  const training=await evaluator.evaluate(folder.at(parentId),{split:'train',seed:policy.seed??0});\n  const evidence=evaluator.page(training.evidence);\n  return {evidence,opportunity:await decide.findOpportunity(policy,opportunityFacts(policy,evidence))};\n}\n",
  "improveStep/findOpportunity.nl": "---\nargs:\n  facts: OpportunityFacts\nreturns: Opportunity\n---\nSay what the next experiment on the program should look at. facts.rows lists the training rows (caseId, passed, modelCalls, failureKind) and facts.objective is `quality`, `source-size` or `model-calls`.\n\n1. When a row has failureKind `fixture`, return kind `fixture` and a reason that says the independent fixture failed before the program ran.\n2. When a row has passed false, return kind `quality` and a reason that names the failed case ids.\n3. When facts.objective is `model-calls` and a passing row used more than one model request, return kind `efficiency` and a reason that names those case ids and says the cost objective is still open.\n4. When facts.objective is `source-size`, return kind `source-size` and a reason that says a behavior-preserving simplification can be measured.\n5. Otherwise return kind `none` and the reason \"No observed failure or cost opportunity supports this objective.\"\n",
  "improveStep/hypothesize.nl": "---\nargs:\n  request: HypothesizeRequest\nreturns: Hypothesis\n---\nChoose the one edit to the program source that the diagnosis supports, and describe it. A hypothesis is a testable explanation with the edit that follows from it.\n\n1. Read request.diagnosis.pattern, then the text of the files in request.sourceFiles that the observations point to.\n2. Choose the smallest edit that explains the pattern. `instruction` rewrites an instruction. `helper` corrects exact code such as a join, a file pattern, a superseded record or a trimmed edit string. `structure` reorganizes the program, for example a root reducer that reads a small batch, judges its meaning directly and does the exact bookkeeping in one final eval; use `structure` when request.mode is `structural`. `efficiency` removes a model request or tool call that the results show to be unnecessary.\n3. For an observation of category `execution-method`, choose the edit that makes the program use its ordinary file tools or scoped folder handles.\n4. Compare with request.history. Choose an edit that differs from every rejected outcome in kind or in files.\n5. Set files to the paths the edit changes. Every path is one of request.allowedFiles.\n6. Set statement to one sentence naming the observed failure or wasted action the edit addresses. Set predictedChange to the measurement you expect to move.\n7. When request.transformation is present, it names the kind of change this run performs; choose the edit within that kind.\n8. When the evidence supports no edit, return kind `none`, an empty files list and a statement that says why.\n",
  "improveStep/lifecycle.ts": "import type {ImprovementPolicy,SearchState} from '../types';\nimport {start} from './baseline';\nimport {advance} from './population';\nimport type {ExperimentFolder,ExperimentEvaluator,PlanJournal,Snapshot} from './capabilities';\nimport {test} from './experiment';\nimport {decisions} from './policies';\ntype Folder=ExperimentFolder & {snapshot():Snapshot;select(source:unknown):Promise<void>};\n/** What is decided before an experiment's edit: recorded in the journal so a resumed run reuses it. */\ntype Plan={parent:string;chose:{chooseParent:string}};\n\n/**\n * The plan of experiment `iteration`: the journaled one when this experiment was already planned (a resumed run), else\n * the parent the policy chooses now, recorded before the edit begins.\n */\nasync function plan(plans:PlanJournal,state:SearchState,policy:ImprovementPolicy):Promise<Plan> {\n  const recalled=await plans.recall(state.iteration) as Plan|null;\n  if(recalled&&state.population.some(member=>member.source===recalled.parent))return recalled;\n  const parent=policy.strategy==='gepa'?await decisions.chooseParent(policy,state.population,state.history,(policy.seed??0)+state.iteration+1):state.incumbent;\n  const decided:Plan={parent,chose:{chooseParent:policy.strategy==='gepa'?policy.policies?.chooseParent??'crisp':'incumbent'}};\n  await plans.record(state.iteration,decided);\n  return decided;\n}\n\n/** One finite experiment by construction: plan, then one semantic diagnose/hypothesize/edit and test, exact selection. */\nexport async function step(folder:Folder,evaluator:ExperimentEvaluator,plans:PlanJournal,state:SearchState,policy:ImprovementPolicy):Promise<SearchState> {\n  const source=folder.snapshot();\n  const validation=await evaluator.evaluate(source,{split:'validation',seed:policy.seed??0});\n  const current=state.iteration===0?start(state,validation):state;\n  const frame={current,baselineBytes:current.population[0].cost??validation.sourceBytes};\n  const planned=await plan(plans,current,policy);\n  const experiment=await test(folder,evaluator,planned.parent,policy,current,decisions);\n  return await advance(folder,evaluator,frame,experiment,policy,decisions);\n}\n",
  "improveStep/policies.ts": "import {pluggable} from '@natlang/node';\nimport findOpportunityNl from './findOpportunity.nl';\nimport chooseParentNl from './chooseParent.nl';\nimport selectIncumbentNl from './selectIncumbent.nl';\nimport shouldStopNl from './shouldStop.nl';\nimport diagnose from './diagnose.nl';\nimport hypothesize from './hypothesize.nl';\nimport editSource from './editSource.nl';\nimport editSourceStructural from './editSourceStructural.nl';\nimport type {ExperimentOutcome,ImprovementPolicy,Opportunity,OpportunityFacts,PopulationMember,StopDecision,StopFacts} from '../types';\nimport type {Decisions} from './capabilities';\nimport {crispIncumbent,crispOpportunity,crispParent,crispStop,incumbentChoices,parentChoices,verifyIncumbent,verifyOpportunity,verifyParent,verifyStop} from './crisp';\n\n/**\n * The decisions of one experiment, each a natural-language function or a pluggable policy. `policy.policies.<name>`\n * selects `crisp` (the default), `nl` or `shadow` (both run, the crisp result is served, and the trace records whether\n * they agree). A natural-language choice is bounded by the crisp verifier beside it (crisp.ts); a choice outside the\n * bound is an error that says what the bound is.\n */\nexport function findOpportunity(policy:ImprovementPolicy,facts:OpportunityFacts):Promise<Opportunity> {\n  return pluggable<[OpportunityFacts],Opportunity>({crisp:async value=>crispOpportunity(value),nl:async value=>verifyOpportunity(await findOpportunityNl(value),value)},\n    policy.policies?.findOpportunity,{name:'findOpportunity',default:'crisp',serve:'crisp'})(facts);\n}\nexport function chooseParent(policy:ImprovementPolicy,population:PopulationMember[],history:ExperimentOutcome[],seed:number):Promise<string> {\n  return pluggable<[PopulationMember[],ExperimentOutcome[],number],string>({\n    crisp:async (all,_history,draw)=>crispParent(all,draw),\n    nl:async (all,past)=>verifyParent(await chooseParentNl(parentChoices(all,past)),all)},\n    policy.policies?.chooseParent,{name:'chooseParent',default:'crisp',serve:'crisp'})(population,history,seed);\n}\nexport function selectIncumbent(policy:ImprovementPolicy,population:PopulationMember[],incumbent:string):Promise<string> {\n  const objective=policy.objective??'quality';\n  return pluggable<[PopulationMember[],string],string>({\n    crisp:async (all,current)=>crispIncumbent(all,current,objective),\n    nl:async (all,current)=>verifyIncumbent(await selectIncumbentNl(incumbentChoices(all,objective),current,objective),all,objective)},\n    policy.policies?.selectIncumbent,{name:'selectIncumbent',default:'crisp',serve:'crisp'})(population,incumbent);\n}\nexport function shouldStop(policy:ImprovementPolicy,facts:StopFacts):Promise<StopDecision> {\n  return pluggable<[StopFacts],StopDecision>({crisp:async value=>crispStop(value),nl:async value=>verifyStop(await shouldStopNl(value),value)},\n    policy.policies?.shouldStop,{name:'shouldStop',default:'crisp',serve:'crisp'})(facts);\n}\n\n/** What one experiment decides with: the policies and the semantic stages. */\nexport const decisions:Decisions={findOpportunity,chooseParent,selectIncumbent,shouldStop,diagnose,hypothesize,\n  editor:mode=>mode==='structural'?editSourceStructural:editSource};\n",
  "improveStep/population.ts": "import {prune} from 'natlang:gepa';\nimport type {SearchState,PopulationMember,ExperimentFeedback,ExperimentOutcome} from '../types';\nimport {members} from './crisp';\nimport type {Decisions} from './capabilities';\ntype MeasuredSource = {source:string;quality:number;sourceBytes?:number;scores?:{caseId:string;quality:number}[]};\n/** Exact state assembly. The caller makes every acceptance, selection and stopping decision. */\nexport function finishStep(state:SearchState,selected:MeasuredSource,population:PopulationMember[],experiment:ExperimentOutcome,done:boolean,stopReason:string,lastExperiment?:ExperimentFeedback):SearchState {\n  if (!population.some(member=>member.source===selected.source && member.quality===selected.quality)) throw Error('selected source and quality must be in the population');\n  return {iteration:state.iteration+1,done,incumbent:selected.source,quality:selected.quality,population,\n    history:[...state.history,experiment],stopReason,...(lastExperiment?{lastExperiment}:{})};\n}\n\n/** The population cut to the limit: the baseline and the selected member stay, then the frontier, then higher quality. */\nexport function trim(population:PopulationMember[],selected:string,limit:number):PopulationMember[] {\n  if(!Number.isSafeInteger(limit)||limit<2)throw Error('population limit must retain baseline and incumbent');\n  const baseline=population.filter(member=>member.parent==='').map(member=>member.source);\n  const kept=prune(members(population),[selected,...baseline],limit).map(member=>member.id);\n  return population.filter((member,index)=>kept.includes(member.source)&&population.findIndex(other=>other.source===member.source)===index);\n}\n\n/** Install a measured population member independently of accepting a draft. */\nexport async function advance(folder:{at(source:string):unknown;select(source:unknown):Promise<void>},evaluator:{evaluate(source:any,request:{split:'validation';seed:number}):Promise<MeasuredSource>},frame:import('../types').SearchFrame,experiment:import('../types').ExperimentResult,policy:import('../types').ImprovementPolicy,decide:Pick<Decisions,'selectIncumbent'|'shouldStop'>):Promise<SearchState> {\n  const added=experiment.accepted?[...frame.current.population,{source:experiment.source,quality:experiment.quality,parent:experiment.parent,cost:experiment.sourceBytes,...(experiment.modelCalls!==undefined?{modelCalls:experiment.modelCalls}:{}),scores:experiment.scores}]:frame.current.population;\n  const selected=await decide.selectIncumbent(policy,added,frame.current.incumbent);\n  const population=trim(added,selected,policy.maxPopulation);\n  await folder.select(folder.at(selected));\n  const measured=await evaluator.evaluate(folder.at(selected),{split:'validation',seed:policy.seed??0});\n  const outcome:ExperimentOutcome={source:experiment.source,parent:experiment.parent,accepted:experiment.accepted,selected:experiment.accepted&&selected===experiment.source,reason:experiment.reason,disposition:experiment.disposition,...(experiment.candidate?{candidate:experiment.candidate}:{}),...(experiment.failing?{failing:experiment.failing}:{})};\n  const recent=[...frame.current.history,outcome].slice(-3).map(entry=>({disposition:entry.disposition??(entry.accepted?'accepted':'rejected'),failingCases:entry.failing??[]}));\n  const decision=await decide.shouldStop(policy,{disposition:experiment.disposition,reason:experiment.reason,selectedQuality:measured.quality,objective:policy.objective??'quality',iteration:frame.current.iteration,maxExperiments:policy.maxExperiments,recent});\n  return finishStep(frame.current,measured,population,outcome,decision.stop,decision.reason,experiment.feedback);\n}\n",
  "improveStep/selectIncumbent.nl": "---\nargs:\n  candidates: IncumbentChoice[]\n  incumbent: string\n  objective: string\nreturns: string\n---\nChoose which candidate becomes the incumbent. Every candidate already has the highest validation quality, and the objective's measure (source size for `source-size`, model requests for `model-calls`) already ties between them.\n\n1. When one candidate has the id `incumbent`, return that id.\n2. Otherwise compare the candidates by sourceBytes and modelCalls, smaller first, and return the id of the smallest.\n3. When several remain, return the smallest id.\n",
  "improveStep/shouldStop.nl": "---\nargs:\n  facts: StopFacts\nreturns: StopDecision\n---\nDecide whether the improvement search ends after this experiment. facts describes the experiment that just finished (disposition, reason), the selected quality, the objective, the experiment count and facts.recent (the last experiments with the cases they failed).\n\n1. When facts.disposition is `fixture-error`, stop with facts.reason.\n2. When facts.objective is `quality` and facts.selectedQuality is 1, stop with the reason \"Declared objective satisfied.\"\n3. When facts.disposition is `no-hypothesis` or `no-opportunity`, stop with the reason \"No further evidenced change.\"\n4. When facts.iteration + 1 reaches facts.maxExperiments, stop with the reason \"Declared experiments completed.\"\n5. When the last three entries of facts.recent were rejected and name the same failing cases, stop with the reason \"The last three experiments failed the same cases.\"\n6. Otherwise continue, with the reason \"Continue with a distinct hypothesis.\"\n",
  "improveStep/transformations.ts": "/**\n * The kinds of change a run can perform, each as one sentence of instruction. `policy.transformation` names one; the\n * diagnose, hypothesize and edit stages read the sentence as `request.transformation`. The names are the former\n * `reducers/<name>.nl` files; a name is a key here and the host's workflow functions (`repairProgram`, ...) use it.\n */\nexport const TRANSFORMATIONS:Record<string,string>={\n  clarifyInstructions:'Rewrite vague and contradictory instructions into clear executable semantic rules, using concrete input roles and explicit negative or missing-information outcomes. Retain behavior and contracts.',\n  extractHelper:'Extract a repeated semantic judgment into a typed named natural-language helper with a companion folder. Retain external behavior and finite control flow.',\n  implementProgram:'Implement the requested application in native natlang: named semantic functions and directory reducers, typed contracts, finite exact helpers and folder.iterateOn for bounded improvement. Preserve the pinned external entry.',\n  removeDuplicatedGuidance:'Remove duplicated or contradictory instructions. Keep each rule in the narrowest appropriate scope; retain externally required behavior.',\n  repairProgram:'Repair a program using supplied failure evidence. Change semantics or structure as justified, preserve regressions and the external entry, and explain the hypothesis tested.',\n  simplifyProgram:'Simplify the native semantic program. Remove unnecessary machinery, make semantic decisions explicit in natlang, retain finite execution and external behavior.',\n  specializeForModel:'Simplify instructions and API usage for an underpowered coding model using observed failures. Prefer explicit folder.propose, evaluator.check/evaluate, folder.accept and folder.select. Base each change on observed failures so it holds across cases.',\n};\n\n/** The instruction sentence of a named transformation; an unknown name lists the known ones. */\nexport function transformationText(name:string):string {\n  const text=TRANSFORMATIONS[name];\n  if(text===undefined)throw Error('A transformation is one of: '+Object.keys(TRANSFORMATIONS).join(', ')+'.');\n  return text;\n}\n",
  "improveStep.nl": "---\nkind: directory-reducer\nargs:\n  state: SearchState\n  policy: ImprovementPolicy\nreturns: SearchState\n---\nImprove this source through one evidenced experiment. Return `await lifecycle.step(folder, evaluator, plans, state, policy)` in eval with finish:true. The authored helpers plan the experiment, measure the source and its training feedback, ask the diagnose, hypothesize and edit functions for one change to the private folder, then check, measure and select the result. Return a rejected or unchanged experiment honestly. The outer folder.iterateOn owns repetition; one experiment runs per step, with the scores the host measured.\n",
  "types.ts": "export type Objective='quality'|'source-size'|'model-calls';\nexport type PolicyMode='crisp'|'nl'|'shadow';\n/** The mode of each pluggable search policy; an absent policy runs its crisp default. */\nexport type PolicySettings={findOpportunity?:PolicyMode;chooseParent?:PolicyMode;selectIncumbent?:PolicyMode;shouldStop?:PolicyMode;chooseMove?:PolicyMode;chooseComponents?:PolicyMode};\n/** How an experiment ended. The text in `reason` is for reading; decisions use this. */\nexport type Disposition='accepted'|'rejected'|'no-hypothesis'|'no-opportunity'|'fixture-error'|'invalid-candidate'|'duplicate';\nexport type PopulationMember = {source:string;quality:number;parent:string;cost?:number;modelCalls?:number;scores?:{caseId:string;quality:number}[]};\nexport type ExperimentOutcome = { source: string; parent: string; accepted: boolean; selected: boolean; reason: string; disposition?: Disposition; candidate?: string; failing?: string[] };\nexport type SearchState = { iteration: number; done: boolean; incumbent: string; quality: number; population: PopulationMember[]; history: ExperimentOutcome[]; stopReason: string; lastExperiment?:ExperimentFeedback };\nexport type ImprovementPolicy = {seed?:number; maxExperiments: number; mode: 'instruction' | 'structural'; strategy: 'gepa' | 'adaptive'; objective?:Objective; goal: string; outerLesson?:string; allowedFiles: string[]; maxPopulation: number; transformation?:string; policies?:PolicySettings };\nexport type SourceFile = {path:string;text:string};\n\nexport type Opportunity = {kind:'fixture'|'quality'|'efficiency'|'source-size'|'none';reason:string};\nexport type Observation = {caseId:string;whatHappened:string;expected:string;category:'wrong-result'|'execution-method'|'wasted-action'|'fixture'};\nexport type Diagnosis = {observations:Observation[];pattern:string};\nexport type DiagnoseRequest = {evidence:unknown[];brief:string;goal:string;objective:Objective;opportunity:Opportunity;history:ExperimentOutcome[];lastExperiment?:ExperimentFeedback};\nexport type Hypothesis = {kind:'instruction'|'helper'|'structure'|'efficiency'|'none';statement:string;files:string[];predictedChange:string};\nexport type HypothesizeRequest = {diagnosis:Diagnosis;sourceFiles:SourceFile[];mode:'instruction'|'structural';allowedFiles:string[];history:ExperimentOutcome[];transformation?:string};\n/** What the edit stage reads. The host derives the changed paths from the diff. */\nexport type EditRequest = {brief:string;goal:string;mode:'instruction'|'structural';objective?:Objective;hypothesis:Hypothesis;diagnosis:Diagnosis;sourceFiles:SourceFile[];allowedFiles:string[];serviceDeclarations?:Record<string,string>;transformation?:string;preserves?:string[];changes?:string[];checks?:string[]};\nexport type EditResult = { summary: string; preserves: string[] };\n\n/** Facts the search policies decide from (all computed by crisp code). */\nexport type ParentChoice = {id:string;quality:number;wonCases:string[];timesParent:number};\nexport type IncumbentChoice = {id:string;quality:number;sourceBytes?:number;modelCalls?:number};\nexport type StopDecision = {stop:boolean;reason:string};\nexport type StopFacts = {disposition:Disposition;reason:string;selectedQuality:number;objective:Objective;iteration:number;maxExperiments:number;recent:{disposition:Disposition;failingCases:string[]}[]};\nexport type OpportunityFacts = {objective:Objective;rows:{caseId:string;passed:boolean;modelCalls?:number;failureKind?:string}[]};\nexport type MoveFacts = {iteration:number;members:{id:string;changedKeys:string[]}[]};\nexport type ComponentFacts = {eligible:{key:string;coveredCases:number;failingCases:number;proposals:number;accepts:number}[]};\n\nexport type ComponentValue = {kind:'program.guidance';text:string} | {kind:'lambda.instructions';template:{segments:string[];slotIds:string[]}};\nexport type Candidate = Record<string,ComponentValue>;\nexport type ComponentRewriteRequest = {keys:string[];components:unknown[];feedback:unknown};\nexport type ComponentLoopState = {iteration:number;incumbent:string;done:boolean;stopReason:string};\nexport type CounterexampleRequest={goal:string;evidence:unknown[];maxSuggestions?:number};\nexport type CounterexampleSuggestions={inputs:unknown[][];reason:string};\nexport type CounterexampleState={round:number;done:boolean;suite:string;remainingChecks:number;quality:number;reason:string};\nexport type SearchFrame = {current:SearchState;baselineBytes:number};\nexport type ExperimentResult = {source:string;parent:string;accepted:boolean;disposition:Disposition;reason:string;candidate?:string;failing?:string[];quality:number;sourceBytes:number;modelCalls?:number;scores:{caseId:string;quality:number}[];feedback?:ExperimentFeedback};\n\n\nexport type SkillUseEvent={kind:'skill_use';phase:'offered'|'body_read'|'support_file_read'|'helper_invoked';skill_name:string;skill_revision:string;invocation_id?:string|null;path?:string;helper_export?:string;interpretation?:'listed_in_invocation_opening_not_awareness'};\nexport type TrainingEvidence={caseId?:string;quality?:number;gates?:Record<string,boolean>;evidence?:string;modelTraceTruncated?:boolean;expectedFiles?:Record<string,string>;files?:Record<string,string>;passed:boolean;modelCalls?:number;failureKind?:string;error?:string;value?:unknown;expected?:unknown;args?:unknown[];modelTrace?:{calls:unknown;observation:string;skillUse?:SkillUseEvent[]}[];skillUseTrace?:SkillUseEvent[];serviceDeclarations?:Record<string,string>};\n\nexport type ExperimentFeedback={diagnostics?:string[];sourceFiles:SourceFile[];training:TrainingEvidence[];validation?:{quality:number;modelCalls?:number};reason:string};\n"
} as const;
